let currentDate = new Date();
let currentMonth = currentDate.getMonth();
let currentYear = currentDate.getFullYear();
let selectedDate = null;

// CALENDARIO
function updateCalendar() {
    const calendarGrid = document.getElementById('calendarGrid');
    const monthYearElement = document.getElementById('currentMonthYear');

    const monthNames = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',
                        'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    monthYearElement.textContent = `${monthNames[currentMonth]} ${currentYear}`;

    calendarGrid.innerHTML = '';

    const dayNames = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
    dayNames.forEach(day => {
        const el = document.createElement('div');
        el.className = 'calendar-day-name';
        el.textContent = day;
        calendarGrid.appendChild(el);
    });

    const firstDay = new Date(currentYear, currentMonth, 1).getDay();
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

    for (let i = 0; i < firstDay; i++) {
        const empty = document.createElement('div');
        empty.className = 'calendar-day empty';
        calendarGrid.appendChild(empty);
    }

    for (let day = 1; day <= daysInMonth; day++) {
        const dayEl = document.createElement('div');
        dayEl.className = 'calendar-day';
        dayEl.textContent = day;

        const dateKey = `${String(currentMonth + 1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;

        if (bolivianEvents[dateKey]) {
            dayEl.classList.add('has-event');
            dayEl.title = bolivianEvents[dateKey].title;
        }

        if (selectedDate === day) dayEl.classList.add('selected');

        dayEl.addEventListener('click', () => selectDate(day, dateKey));
        calendarGrid.appendChild(dayEl);
    }
}

function selectDate(day, dateKey) {
    selectedDate = day;
    document.querySelectorAll('.calendar-day').forEach(d => d.classList.remove('selected'));
    event.target?.classList?.add('selected');

    // marcar visualmente el día seleccionado
    document.querySelectorAll('.calendar-day').forEach(d => {
        if (d.textContent == day && !d.classList.contains('empty')) {
            d.classList.add('selected');
        }
    });

    if (bolivianEvents[dateKey]) {
        displayEventInfo(bolivianEvents[dateKey]);
    } else {
        displayNoEventInfo(day);
    }
}

function getMonthName(monthIndex) {
    const monthNames = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',
                        'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    return monthNames[monthIndex];
}

function changeMonth(delta) {
    currentMonth += delta;
    if (currentMonth < 0) { currentMonth = 11; currentYear--; }
    else if (currentMonth > 11) { currentMonth = 0; currentYear++; }
    selectedDate = null;
    updateCalendar();
    resetInfoSection();
}

function resetInfoSection() {
    document.getElementById('infoSection').innerHTML = `
        <div class="welcome">
            <div class="welcome-icon"><img src="condor_monocromatico-removebg-preview.png" alt="Guía de estudio"></div>
            <h2>Bienvenido a tu Guía de Estudio</h2>
            <p>Selecciona una fecha marcada en <strong>morado</strong> para acceder a información histórica detallada sobre Bolivia.</p>
            <div class="features">
                <span class="feature">✦ Contexto Histórico ✦</span>
                <span class="feature">✦ Datos Curiosos ✦</span>
                <span class="feature">✦ Resumen ✦</span>
                <span class="feature">✦ Imágenes ✦</span>
            </div>
        </div>
    `;

    document.getElementById('curiousFactsContent').innerHTML =
        '<p class="placeholder">Selecciona una fecha del calendario para descubrir datos fascinantes</p>';

    const imagesGrid = document.getElementById('imagesGrid');
    if (imagesGrid) {
        imagesGrid.innerHTML = '<p class="placeholder">Selecciona una fecha para ver imágenes</p>';
    }
}
// MOSTRAR EVENTO HISTÓRICO
// MOSTRAR EVENTO HISTÓRICO
function displayEventInfo(eventData) {
    const infoSection = document.getElementById('infoSection');
    const curiousFactsContent = document.getElementById('curiousFactsContent');
    const imagesGrid = document.getElementById('imagesGrid');

    const lugarPrincipal = eventData.title
        .replace(/^(Día|Aniversario|Fiesta|Revolución|Creación|Fundación|Fallecimiento|Batalla)\s+(de(l)?\s+)?/i, '')
        .trim();

    const busquedas = [
        `${eventData.title} Bolivia`,
        `${lugarPrincipal} paisaje Bolivia`,
        `Bolivia cultura ${lugarPrincipal}`
    ].map(q => encodeURIComponent(q));

    const imagesHtml = busquedas.map((query, i) => {
        const imgUrl = `https://tse1.mm.bing.net/th?q=${query}&w=400&h=300&c=7&rs=1&p=0&dpr=1&pid=1.7&mkt=es-BO&adlt=strict`;
        return `
            <div class="img-card">
                <img src="${imgUrl}" alt="${eventData.title} - imagen ${i + 1}" loading="lazy" onerror="this.onerror=null; this.src='https://placehold.co/400x300/5c1d1d/b5bd7a?text=${encodeURIComponent(eventData.title)}';">
                <span>${eventData.title} · ${['Vista general', 'Paisaje', 'Cultura'][i]}</span>
            </div>
        `;
    }).join('');

    const contextoFormateado = eventData.historicalContext
        .split('\n\n')
        .map(p => `<p>${resaltarTexto(p)}</p>`)
        .join('');

    const resumenResaltado = resaltarTexto(eventData.summary);

    const factsHtml = eventData.curiousFacts
        .map(fact => `<li>${resaltarTexto(fact)}</li>`)
        .join('');

    infoSection.innerHTML = `
        <div class="event-header">
            <h2>${resaltarTexto(eventData.title)}</h2>
            <span class="event-date">꧁   ${eventData.date}</span>
        </div>

        <h3 class="section-title">🕮 Contexto Histórico</h3>
        <div class="historical-context">
            ${contextoFormateado}
        </div>

        <h3 class="section-title">📝 Resumen para tu Cuaderno</h3>
        <div class="summary-box">
            <p>${resumenResaltado}</p>
        </div>
    `;

    curiousFactsContent.innerHTML = `<ul class="facts-list">${factsHtml}</ul>`;

    if (imagesGrid) {
        imagesGrid.innerHTML = imagesHtml;
    }
}
function displayNoEventInfo(day) {
    const infoSection = document.getElementById('infoSection');
    const curiousFactsContent = document.getElementById('curiousFactsContent');
    const imagesGrid = document.getElementById('imagesGrid');

    infoSection.innerHTML = `
        <div class="welcome">
            <div class="welcome-icon"><img src="condor_monocromatico-removebg-preview.png" alt="Guía de estudio"></div>
            <h2>${day} de ${getMonthName(currentMonth)}</h2>
            <p>No hay eventos históricos registrados para esta fecha.</p>
            <p>Explora otras fechas marcadas en <strong>morado</strong> para descubrir eventos importantes de Bolivia.</p>
        </div>
    `;

    curiousFactsContent.innerHTML = `<p class="placeholder">Selecciona una fecha para ver datos curiosos</p>`;

    if (imagesGrid) {
        imagesGrid.innerHTML = `<p class="placeholder">Selecciona una fecha para ver imágenes</p>`;
    }
}
