const KEYWORDS_TO_HIGHLIGHT = [
    'Túpac Katari','Tomás Katari','Bartolina Sisa','Eduardo Abaroa',
    'Pedro Domingo Murillo','Simón Bolívar','Antonio José de Sucre',
    'Sebastián Pagador','Alonso de Mendoza','Francisco Tito Yupanqui',
    'Ñuflo de Chaves','Víctor Paz Estenssoro','Evo Morales',
    'Gonzalo Sánchez de Lozada','Carlos Mesa','Andrés de Santa Cruz',
    'Independencia','Revolución Nacional','Revolución de Oruro',
    'Revolución de Chuquisaca','Revolución de La Paz',
    'Primer Grito Libertario','Acta de Independencia',
    'Constitución Política del Estado','Estado Plurinacional',
    'Nacionalización','Referéndum','Asamblea Constituyente',
    'Guerra del Pacífico','Guerra del Gas','Reforma Agraria',
    'Batalla de Ayacucho','Batalla de Calama','Masacre de San Juan',
    'Tiwanaku','Chuquisaca','Sucre','Potosí','Oruro','La Paz',
    'Santa Cruz','Cochabamba','El Alto','Copacabana','Lago Titicaca',
    'Cerro Rico','Salar de Uyuni','Illimani','Kalasasaya',
    'Aymaras','Quechuas','Guaraníes','Chiquitanos','Mojeños',
    'Pachamama','Wiphala','Inti Raymi','Willka Kuti',
    'Mita','Latifundio','Pongueaje','Minifundio','Hidrocarburos',
    'Plata','Estaño','Gas Natural','Mediterraneidad',
    'Reivindicación Marítima','Sincretismo Religioso',
    'Diversidad Cultural','Pueblos Indígenas Originarios'
];

// ============================================================
// 2. FUNCIÓN DE RESALTADO
// ============================================================
function resaltarTexto(texto) {
    if (!texto) return '';
    let resultado = texto;

    resultado = resultado.replace(
        /\b(1[4-9]\d{2}|20\d{2}|2100)\b(?![^\s]*\.(?:jpg|png|gif|webp|svg|jpeg))/gi,
        '<span class="highlight-date">$1</span>'
    );

    const meses = ['enero','febrero','marzo','abril','mayo','junio',
                   'julio','agosto','septiembre','octubre','noviembre','diciembre'];
    const regexFecha = new RegExp(
        `\\b(\\d{1,2}\\s+de\\s+(?:${meses.join('|')}))\\b`, 'gi'
    );
    resultado = resultado.replace(regexFecha, '<span class="highlight-date">$1</span>');

    const ordenadas = [...KEYWORDS_TO_HIGHLIGHT].sort((a, b) => b.length - a.length);
    ordenadas.forEach(keyword => {
        const esc = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const tieneEspacios = keyword.includes(' ');
        const regex = tieneEspacios
            ? new RegExp(`(${esc})`, 'gi')
            : new RegExp(`\\b(${esc})\\b`, 'gi');
        resultado = resultado.replace(regex, '<span class="highlight-keyword">$1</span>');
    });

    resultado = resultado.replace(
        /<span class="highlight-(keyword|date)">\s*<span class="highlight-(keyword|date)">([^<]*)<\/span>\s*<\/span>/g,
        '<span class="highlight-$2">$3</span>'
    );

    return resultado;
}

